<script setup lang="ts">
import { ref } from 'vue'
import {readChatFiles} from './intake'
import { httpClient } from '@/shared/http/client'
import type { DraftForm,WorkOrder } from './work-orders'
import { draftLabels,mergeOcrDraft,ocrDraftPayload,prefillOcrDraft,type OcrFieldConflict } from '../materials/ocr-form'
const props=defineProps<{form:DraftForm;locked:boolean}>(),emit=defineEmits<{merge:[value:DraftForm];blocked:[value:boolean];photos:[files:File[]]}>()
const ambiguities=ref<{field:keyof DraftForm;values:string[]}[]>([])
const text=ref(''),source=ref(''),busy=ref(false),confirmed=ref(false),message=ref(''),conflicts=ref<OcrFieldConflict[]>([]),candidate=ref<Record<string,unknown>>({}),key=ref(crypto.randomUUID())
async function importText(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files??[]);if(!files.length)return;busy.value=true;confirmed.value=false;emit('blocked',true);message.value='';try{const imported=await readChatFiles(files);text.value=imported.text;changed();if(input.hasAttribute('webkitdirectory'))emit('photos',imported.photos)}catch(error){message.value=error instanceof TypeError?'TXT编码无法读取，请转为UTF-8后导入':error instanceof Error?error.message:'导入失败'}finally{input.value='';busy.value=false;emit('blocked',Boolean(text.value.trim())||Boolean(message.value))}}
function changed(){confirmed.value=false;source.value='';conflicts.value=[];ambiguities.value=[];key.value=crypto.randomUUID();emit('blocked',Boolean(text.value.trim()))}
async function extract(){busy.value=true;message.value='';confirmed.value=false;emit('blocked',true);try{candidate.value=(await httpClient.post<{data:Record<string,unknown>}>('/work-orders/text/extract',{text:text.value})).data.data;source.value=text.value;const result=mergeOcrDraft(props.form,(candidate.value.fields??{}) as Record<string,unknown>);emit('merge',result.merged);conflicts.value=result.conflicts;const evidence=(candidate.value.evidence??{}) as Record<string,{value?:string;requiresConfirmation?:boolean}[]>;ambiguities.value=Object.entries(evidence).filter(([field,rows])=>field in draftLabels&&field!=='accidentRegionId'&&(new Set(rows.map(row=>row.value).filter(Boolean)).size>1||rows.some(row=>row.requiresConfirmation))).map(([field,rows])=>({field:field as keyof DraftForm,values:[...new Set(rows.map(row=>row.value).filter((value):value is string=>typeof value==='string'))]}))}catch(error){message.value=error instanceof Error?error.message:'提取失败'}finally{busy.value=false}}
function resolve(item:OcrFieldConflict,useSource:boolean){if(useSource)emit('merge',{...props.form,[item.field]:item.incoming});conflicts.value=conflicts.value.filter(c=>c.field!==item.field)}
async function selectAmbiguity(field:keyof DraftForm,value?:string){if(value!==undefined){busy.value=true;try{const name=field==='accidentAt'?'事故时间':field==='claimReportedAt'?'报案时间':draftLabels[field];const result=(await httpClient.post<{data:{fields:Record<string,string>}}>('/work-orders/text/extract',{text:name+'：'+value})).data.data;const adopted=prefillOcrDraft(result.fields)[field];if(!adopted)throw Error('该候选无法直接采用，请人工填写后选“保留当前输入”');emit('merge',{...props.form,[field]:adopted})}catch(e){message.value=e instanceof Error?e.message:'核对失败';return}finally{busy.value=false}}ambiguities.value=ambiguities.value.filter(item=>item.field!==field)}
async function createReviewedDraft(form:DraftForm):Promise<WorkOrder|undefined>{if(busy.value)throw Error('文字读取或提取中，请稍后');if(!text.value.trim())return undefined;if(!confirmed.value||source.value!==text.value||conflicts.value.length||ambiguities.value.length)throw Error('请提取文字并核对冲突与采用信息');return (await httpClient.post<{data:WorkOrder}>('/work-orders/text/draft',{text:source.value,confirmed:true,draft:ocrDraftPayload(form)},{headers:{'Idempotency-Key':key.value}})).data.data}
defineExpose({createReviewedDraft})
</script>
<template><aside class="text-intake"><h2>导入案件资料</h2><p>文字提取信息，照片仅作物损材料。</p><label>聊天记录文件夹<input type="file" webkitdirectory multiple :disabled="locked||busy" @change="importText"/></label><label>文字文件<input type="file" accept=".txt,text/plain" :disabled="locked||busy" @change="importText"/></label><label>原始文字<textarea v-model="text" :disabled="locked||busy" maxlength="50000" rows="12" placeholder="案件号：…&#10;三者电话：…&#10;查勘员姓名：…" @input="changed"/></label><button :disabled="locked||busy||!text.trim()" @click="extract">{{ busy?'正在提取…':'提取信息' }}</button><p v-if="message" role="alert">{{ message }}</p><article v-for="item in ambiguities" :key="item.field"><strong>{{ draftLabels[item.field] }}待确认</strong><button v-for="value in item.values" :key="value" :disabled="locked||busy" @click="selectAmbiguity(item.field,value)">采用 {{ value }}</button><button :disabled="locked||busy" @click="selectAmbiguity(item.field)">保留当前输入 / 手工填写</button></article><article v-for="item in conflicts" :key="item.field"><strong>{{ draftLabels[item.field] }}有不同值</strong><p>当前：{{ form[item.field] }}<br/>原文：{{ item.incoming }}</p><button @click="resolve(item,false)">保留当前</button><button @click="resolve(item,true)">采用原文</button></article><label v-if="source&&!conflicts.length&&!ambiguities.length"><input v-model="confirmed" type="checkbox" :disabled="locked||busy" @change="emit('blocked',!confirmed)"/>已核对原文与采用信息</label><details v-if="source"><summary>提取依据</summary><pre>{{ JSON.stringify(candidate,null,2) }}</pre></details></aside></template>
<style scoped>.text-intake{padding:24px;background:#f3f7f6;border:1px solid #dce5e4;border-radius:16px}.text-intake h2{margin:0;font-size:20px}.text-intake p{font-size:13px;color:#566a70}.text-intake label{display:block;margin:16px 0}.text-intake textarea{display:block;margin-top:8px;width:100%;box-sizing:border-box;resize:vertical;padding:12px;border:1px solid #b9c9c9;border-radius:8px;font:inherit}.text-intake button{margin:4px}.text-intake article{border-top:1px solid #cbd9d7;padding-top:16px}.text-intake pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}</style>
